CREATE TABLE quizzes (id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(120) NOT NULL,duration_seconds INT NOT NULL);
CREATE TABLE questions (id INT PRIMARY KEY AUTO_INCREMENT,quiz_id INT NOT NULL,body TEXT NOT NULL,FOREIGN KEY (quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE options (id INT PRIMARY KEY AUTO_INCREMENT,question_id INT NOT NULL,label VARCHAR(255) NOT NULL,is_correct BOOLEAN DEFAULT FALSE,FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE);
CREATE TABLE attempts (id INT PRIMARY KEY AUTO_INCREMENT,quiz_id INT NOT NULL,user_id INT,score INT NOT NULL,started_at DATETIME,submitted_at DATETIME);
